-- order_detail: 2023-11-01 ~ 2024-11-30 (2024-11은 API 데이터와 대조용)
SELECT YN_SET_OPTION, POTOTAL, SERVICE_AMT, COUPON_VALUE, YN_VAT, ID_MENU, INV_STS, QTY_DELIVERY, INV_TYPE, QTY, SALE_STAT, ID_CODE, DC_USED_RATE, UP_DATE, DIFF_AMT, TAXRATE, POS_NO, STORE_CODE, QTY_SERVICE, YN_TAX, SUMPRICE, YN_COUPON, ID_DESC, DC_USED_TYPE, POPRICE, PRODUCT_AMT, DC_REASON_CODE, YN_END, DEPOSIT_FEE, SERVICE_FEE, YN_SET, ID_MEMO, NET_AMT, ETC_CHARGE, COUPON_AMT, ID_MENUNAME, COMPANY_ID, QTY_PACKING, QTYPRICE, ROW_NUM, SUB_TOT, SALE_DATE, GRAND_TOTAL, ADD_PRICE, YN_SERVICE, INV_NOS, POSPRICE, NOTAX_TOT, ID_ALTC, CR_DATE, INV_SEQ, COUPON_CODE, YN_NOTAX, DATA_STAT, POINT, DC_REASON_DESC, COUPON_COUNT, TAX_TOT
FROM order_detail
WHERE SALE_DATE >= '2023-11-01' AND SALE_DATE < '2024-12-01';
